<?php $q=is_string($_GET['q']??'')?trim($_GET['q']??''):'';$page=max(1,min(100,(int)($_GET['page']??1)));$valid=mb_strlen($q)>=2&&mb_strlen($q)<=80;$found=($valid||$q==='')?searchGuides($articles,$q):[];?>
<section class="page-heading"><span class="eyebrow">שאלה טובה היא התחלה של תוכנית</span><h1>מה מתכננים הפעם?</h1><form action="/search/" class="search-form"><label class="sr-only" for="q">חיפוש מדריכים</label><input id="q" name="q" value="<?=e($q)?>" placeholder="יעד, חופשה עם ילדים, כבודה…" minlength="2" maxlength="80"><button class="button">חיפוש מדריכים ←</button></form><p>חפשו לפי יעד או לפי שאלה שמעסיקה אתכם.</p></section>
<?php $activityMatches=($valid&&$page===1)?activityResults(['q'=>$q]):[];if($activityMatches):?><section class="section"><h2><?=e(languagePhrase('חוויות ומחירים','Experiences & prices','Впечатления и цены'))?></h2><a href="/experiences/?q=<?=urlencode($q)?>"><?=e(languagePhrase('סינון לפי יעד, סוג ומחיר','Filter by destination, type and price','Фильтровать результаты'))?></a><div class="activity-grid"><?php foreach($activityMatches as $a)activityCard($a,'search');?></div></section><?php endif?><?php if($q!==''&&!$valid):?><p class="notice error">הזינו בין 2 ל־80 תווים.</p><?php elseif($valid):?><p class="notice"><?=e(sprintf(languagePhrase('%d מדריכים עבור ״%s״','%d guides for “%s”','%d путеводителей по запросу «%s»'),count($found),$q))?></p><?php endif?>
<?php if(!$q):?><p class="notice"><?=e(sprintf(languagePhrase('כל %d המדריכים שלנו — בחרו נושא או חפשו שאלה.','All %d guides — choose a topic or search for a question.','Все %d путеводителей — выберите тему или задайте вопрос.'),count($found)))?></p><div class="filter-bar"><?php foreach(['ילדים','תקציב','סקי','מלון','רכב','פראג'] as $word):?><a href="/search/?q=<?=urlencode($word)?>"><?=e($word)?></a><?php endforeach?></div><?php elseif(!$found&&$valid):?><div class="empty-state"><h2>עוד לא מצאנו מדריך מתאים.</h2><p>נסו מילה קצרה יותר או עברו לאחד המדורים.</p><a class="text-link" href="/destinations/">ליעדים ומסלולים ←</a></div><?php endif?><div class="cards"><?php foreach(array_slice($found,($page-1)*20,20) as $a)card($a)?></div><?php if(count($found)>20):?><div class="filter-bar"><?php for($n=1;$n<=ceil(count($found)/20);$n++):?><a href="?q=<?=urlencode($q)?>&page=<?=$n?>"><?=e(languagePhrase('עמוד','Page','Страница'))?> <?=$n?></a><?php endfor?></div><?php endif?>
